probe() {
  ip=$1; port=$2
  out=$(wget -T 2 -O /dev/null "http://$ip:$port/" 2>&1)
  if echo "$out" | grep -q "Saving to"; then echo "OPEN  $ip:$port"; 
  elif echo "$out" | grep -qi "refused"; then :;
  elif echo "$out" | grep -qi "unreachable"; then :;
  elif echo "$out" | grep -qi "timed out"; then echo "FILTERED $ip:$port";
  else echo "OTHER $ip:$port :: $(echo "$out"|tail -1)"; fi
}
for ip in 172.21.0.1 172.21.0.2 172.21.0.3; do
  for port in 80 443 3000 5000 8000 8080 8081 8181 8443 9000 9090 4000 5001 6006 7070; do
    probe $ip $port
  done
done
echo "=== probe done ==="

